scwin.gUpjongJongmok = ""; //업종에 따른 종목
scwin.gFilterType = ""; //"S":종목검색버튼,"O"
scwin.gJongName = ""; //종목명
scwin.ssMarket = "N"; //종목콤보확인

scwin.comboMarket = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    scwin.comboMarket = $c.cp.valueOfIndex(combo_market, "VALUE", combo_market.getSelectedIndex());
    var url = "/submitperson.do?method=searchSubmitPerson&inputMessageId=submitperson&outputMessageId=submitperson&DISCLS_SUBMITPRN_TP_CD=" + scwin.comboMarket + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    txb_jongmokName.setValue("");
    dts_jongmok.DataID = encodeURI(url);
    dts_jongmok.reset();
    $c.cm.ShowWin(grd_jongmok);
};


/********************************************** 
 * 함수명   : Jongmok()
 * 설명       : 가나다라..검색
 ***********************************************/
scwin.Jongmok = function(prevval, nextval) {
    txb_jongmokName.setValue("");
    scwin.skw = "";
    dts_jongmok.UseFilter = "true";
    dts_jongmok.Filter();
    grd_jongmok.Redraw = "false";
    dts_jongmok.sort("+SUBMIT_OBLG_ABBRV", 0);
    //dts_jongmok.sort(); // W-Craft 주석처리 
    var cnt = 0;
    for (i = 1; i <= dts_jongmok.getTotalRow(); i++) {
        var name = dts_jongmok.getCellData(i, "SUBMIT_OBLG_ABBRV").substring(0, 1);
        if (name >= prevval && name < nextval) {
            cnt = i;
            break;
        }
    }
    grd_jongmok.Redraw = "true";
    dts_jongmok.setRowPosition(cnt + 11, 0);
    dts_jongmok.setRowPosition(cnt, 0);
    grd_jongmok.focus();
};


/********************************************** 
 * 함수명   : JongmokName()
 * 설명       : 종목명검색
 ***********************************************/
scwin.JongmokName = function(keyCode) {
    //if(keyCode==13) on_close();
    grd_jongmok.Redraw = "false";
    dts_jongmok.sort("+SUBMIT_OBLG_ABBRV", 0);
    //dts_jongmok.sort(); // W-Craft 주석처리 
    var cnt = 0;
    var len = txb_jongmokName.getValue().length;
    var txtVal = txb_jongmokName.getValue().toUpperCase();
    for (i = 1; i <= dts_jongmok.getTotalRow(); i++) {
        var name = dts_jongmok.getCellData(i, "SUBMIT_OBLG_ABBRV").substring(0, len).toUpperCase();
        if (txtVal == name) {
            cnt = i;
            break;
        }
    }
    if (cnt == 0) {
        dts_jongmok.sort("+SUBMIT_OBLG_NM", 0);
        //dts_jongmok.sort(); // W-Craft 주석처리 
        for (i = 1; i <= dts_jongmok.getTotalRow(); i++) {
            var name = dts_jongmok.getCellData(i, "SUBMIT_OBLG_NM").substring(0, len).toUpperCase();
            if (txtVal == name) {
                cnt = i;
                break;
            }
        }
    }
    grd_jongmok.Redraw = "true";
    dts_jongmok.setRowPosition(cnt + 11, 0);
    dts_jongmok.setRowPosition(cnt, 0);
};


/********************************************** 
 * 함수명   : JongmokSearch()
 * 설명       : 종목명검색
 ***********************************************/
scwin.skw = "";
scwin.JongmokSearch = function() {
    scwin.skw = txb_jongmokName.getValue();
    dts_jongmok.UseFilter = "true";
    dts_jongmok.Filter();
    dts_jongmok.setRowPosition(1, 0);
};


/********************************************** 
 * 함수명   : Confirm()
 * 설명       : 부모창으로 종목코드 전달
 ***********************************************/
scwin.Confirm = async function() {
    //frame.Provider("../").종목코드id
    var pJongCode = dts_jongmok.getCellData(dts_jongmok.getRowPosition(), "FSS_UNQ_NO");
    var pJongNm = dts_jongmok.getCellData(dts_jongmok.getRowPosition(), "SUBMIT_OBLG_ABBRV");
    $c.frame.path("../").submitSearch_Rtn(pJongCode, pJongNm);
    await $c.frame.CloseFrame();
};
scwin.dts_jongmok_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_jongmok);
};
scwin.grd_jongmok_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        scwin.Confirm();
    }
};
scwin.grd_jongmok_OnDblClick = function(row, colid) {
    scwin.Confirm();
};
scwin.img_search_onclick = function() {
    scwin.JongmokName(txb_jongmokName.getValue());
};
scwin.txb_jongmokName_onkeydown = function() {
    if (window.event.keyCode == "13") {
        scwin.JongmokName(window.event.keyCode);
        //JongmokSearch();

    }
};
