scwin.dts_jongmok_OnFilter = function(row) {
    if (scwin.skw != "") {
        f1 = dts_jongmok.getCellData(row, "COM_ABBRV");
        f2 = dts_jongmok.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(scwin.skw) != -1) {
            return true;
        } else if (f2.indexOf(scwin.skw) != -1) {
            return true;
        } else {
            return false;
        }
    } else {
        return true;
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox_01(panel_1);
    $c.cm.PanelToGroupBox_02(panel_2);
    dts_jongmok.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=isurcd";
    dts_jongmok.reset();
    scwin.fn_list_sync();
